<?php require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/auth.php'; require_login(); $kode=$_GET['kode']??''; $st=$pdo->prepare('SELECT * FROM elemen_penilaian WHERE kode=?');$st->execute([$kode]);$ep=$st->fetch(); if(!$ep) die('EP tidak ditemukan'); $st=$pdo->prepare('SELECT d.* FROM dokumen d JOIN dokumen_ep de ON de.dokumen_id=d.id WHERE de.ep_id=? ORDER BY d.nama');$st->execute([$ep['id']]);$docs=$st->fetchAll(); require __DIR__.'/../partials/header.php'; ?><div class="d-flex justify-content-between"><div><h2><?=htmlspecialchars($ep['kode'])?></h2><p><?=htmlspecialchars($ep['judul'])?></p></div><span class="badge text-bg-success align-self-start">Mode Survei</span></div><div class="card shadow-sm border-0 mb-3"><div class="card-body"><h5>Dokumen & Bukti</h5><div class="table-responsive"><table class="table"><thead><tr><th>Dokumen</th><th>Kategori</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($docs as $d):?><tr><td><?=htmlspecialchars($d['nama'])?></td><td><?=htmlspecialchars($d['kategori'])?></td><td><?=htmlspecialchars($d['status'])?></td><td><a href="/MRMIKIT/dokumen/view.php?id=<?=$d['id']?>" class="btn btn-sm btn-outline-success">Lihat</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$docs):?><div class="alert alert-warning">Belum ada dokumen yang ditautkan ke EP ini.</div><?php endif;?></div></div><?php require __DIR__.'/../partials/footer.php';